import assert from "node:assert/strict"
import { createForegroundWorkBudget, createForegroundWorkBudgetMiddleware } from "./src/main/agent/foreground-work-budget.ts"
let actualInvocations = 0
const budget = createForegroundWorkBudget({ yieldCommand() {}, now: () => 0 })
const middleware = createForegroundWorkBudgetMiddleware(budget)
const observations = []
for (const [index, action] of ["observe", "navigate", "observe", "click", "observe"].entries()) {
  const before = actualInvocations
  const result = await middleware.wrapToolCall(
    { toolCall: { name: "bot_browser", id: `probe-${index}`, args: { action } } },
    async () => { actualInvocations++; return "synthetic browser receipt" }
  )
  observations.push({ call: index + 1, tool: "bot_browser", action, reachedHandler: actualInvocations > before, status: result?.status ?? "allowed" })
}
assert.equal(actualInvocations, 4)
assert.equal(observations[4].status, "error")
assert.ok(budget.checkFinal()?.includes("Foreground execution budget reached"))
let clock = 0
const timed = createForegroundWorkBudget({ yieldCommand() {}, now: () => clock })
assert.equal(timed.beforeTool("bot_browser", { action: "navigate" }), undefined)
clock = 30_001
assert.ok(timed.beforeTool("bot_browser", { action: "observe" }))
assert.equal(timed.beforeTool("bot_request_browser_help", {}), undefined)
console.log(JSON.stringify({ kind: "deterministic-middleware-probe", realBrowserUsed: false, realModelUsed: false, observations, ordinaryCallsExecuted: actualInvocations, nextCallBlockedAfter30Seconds: true, browserHelpExemptFromBudget: true, passed: true }, null, 2))
